import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

// Note on expected premiums: every quote step carries the 10 % first
// insurance surcharge (10 % of the policy base premium) and the 5 G
// processing fee; quotes after the first also get the 15 % follow-up
// discount. Claims: 100 G deductible per damage entry, cap = 2 × insurance
// sum. Final amounts round in the MHPCO's favor (premiums up, payouts down).

describe("MHPCO Claim Office", () => {
  describe("quote: base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });
      expect(output).toEqual({ results: [{ premium: 5 }] });
    });
    it("single sword (base 100) → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 115 }] });
    });
    it("single amulet (base 60) → premium 71 G (60 + 6 + 5)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 71 }] });
    });
    it("single staff (base 80) → premium 93 G (80 + 8 + 5)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 93 }] });
    });
    it("single potion (base 40) → premium 49 G (40 + 4 + 5)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 49 }] });
    });
  });

  describe("quote: component blocks (block of 3 alike components)", () => {
    it("2 runes (base 50) → premium 60 G (50 + 5 + 5)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      });
      expect(output).toEqual({ results: [{ premium: 60 }] });
    });
    it("3 runes form a block (base 60) → premium 71 G (60 + 6 + 5)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
          },
        ],
      });
      expect(output).toEqual({ results: [{ premium: 71 }] });
    });
    it.todo("4 runes: no block, block requires exactly 3 (base 100) → premium 115 G");
    it.todo("7 runes (base 175) → premium 198 G (175 + 17.5 + 5 = 197.5, rounded up)");
    it.todo("2 runes + 1 moonstone: no block across different types (base 75) → premium 88 G (87.5 rounded up)");
    it.todo("3 runes + 3 moonstones: two separate blocks (base 120) → premium 137 G (120 + 12 + 5)");
  });

  describe("quote: premium modifiers", () => {
    it.todo("newcomer with a cursed sword → premium 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → premium 145 G (100 + 30 + 10 + 5)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge → premium 115 G");
    it.todo("cursed sword with enchantment 5 → both surcharges apply → premium 195 G (100 + 50 + 30 + 10 + 5)");
    it.todo("customer with exactly 2 years → loyalty discount applies → sword premium 95 G (100 − 20 + 10 + 5)");
    it.todo("customer with 0 years → no loyalty discount → sword premium 115 G");
    it.todo("modifier scope: cursed sword + plain amulet → curse surcharge on the sword's base only → premium 231 G (160 + 50 + 16 + 5)");
    it.todo("long-standing customer's second contract (cursed sword, enchantment 7) → premium 160 G (100 + 50 + 30 − 20 + 10 − 15 + 5)");
  });

  describe("claim: standard reimbursement and deductible", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 → payout 400 G (500 − 100 deductible)");
    it.todo("damage to a rune (no enchantment/material), damage 200 → payout 100 G");
    it.todo("deductible applies once per damaged item: sword 500 + amulet 300 in one incident → payout 600 G");
  });

  describe("claim: special reimbursement clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 → payout 400 G (50 % clause, then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 → payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 → payout 400 G (50 % rule wins over dragon material)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 → payout 400 G (high-enchantment clause applies)");
  });

  describe("claim: payout cap (twice the insurance sum)", () => {
    it.todo("sword + amulet policy → insurance sum 1600, cap 3200: sword damage 600 → payout 500, remainingCap 2700");
    it.todo("sword + 3 runes → insurance sum 1750 (block affects premium only), cap 3500: rune damage 200 → payout 100, remainingCap 3400");
    it.todo("cursed sword → cap 2000 based on unmodified insurance value: claim 1500 → payout 1400, remainingCap 600");
    it.todo("cap exhaustion: sword (cap 2000), two claims of 1500 → first payout 1400 (cap 600), second payout 600 (cap 0)");
  });

  describe("claim: multiple items of the same type", () => {
    it.todo("two swords insured → insurance sum 2000, cap 4000: both damaged 500 each → payout 800 (own deductible each), remainingCap 3200");
  });

  describe("rounding in the MHPCO's favor", () => {
    it.todo("payout of 350.5 G rounds down → steel sword enchantment 9, damage 901 → payout 350 G (450.5 − 100 = 350.5)");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout (schema example: amulet quote then claim)");
    it.todo("quote with unknown item type (broomstick) → exits non-zero, error on stderr, no results on stdout");
    it.todo("claim for an item not covered by the policy (amulet damaged, only sword insured) → exits non-zero with stderr");
    it.todo("claim with more damage entries of a type than insured (two sword damages, one sword) → exits non-zero, whole claim rejected");
    it.todo("claim with negative damage amount (−200) → exits non-zero with stderr");
  });
});

