export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const COMPONENT_TYPES = ["rune", "moonstone"];

const componentBlockAdjustment = (
  items: Item[],
  componentType: string,
): number => {
  const count = items.filter((item) => item.type === componentType).length;
  return count === BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * BASE_PREMIUMS[componentType]
    : 0;
};

const basePremiumFor = (items: Item[]): number =>
  items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0) +
  COMPONENT_TYPES.reduce(
    (total, componentType) => total + componentBlockAdjustment(items, componentType),
    0,
  );

const quotePremium = (basePremium: number): number => {
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(basePremiumFor(quoteStep.items)) }] };
};

