    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
    : 0;
};

const basePremiumFor = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item.type), 0) +
  COMPONENT_TYPES.reduce(
    (total, componentType) => total + componentBlockAdjustment(items, componentType),
    0,
  );

const surchargeFor = (
  items: Item[],
  rate: number,
  applies: (item: Item) => boolean,
): number =>
  items.reduce(
    (total, item) =>
      total + (applies(item) ? rate * basePremiumOf(item.type) : 0),
    0,
  );

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const curseSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);

const highEnchantmentSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);

const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const basePremium = basePremiumFor(items);
  const itemSurcharges =
    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
      ? basePremium * LOYALTY_DISCOUNT_RATE
      : 0;
  const followUpDiscount = isFollowUpContract
    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
    : 0;
  return Math.ceil(
    basePremium +
      itemSurcharges +
      firstInsuranceSurcharge -
      loyaltyDiscount -
      followUpDiscount +
      PROCESSING_FEE,
  );
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const PAYOUT_CAP_MULTIPLIER = 2;

const claimResult = (
  claimStep: ClaimStep,
  policyItems: Item[],
): ClaimResult => {
  const payout = claimStep.incident.damages.reduce(
    (total, damage) => total + (damage.amount - DEDUCTIBLE_PER_DAMAGE),
    0,
  );
  const insuranceSum = policyItems.reduce(
    (total, item) => total + INSURANCE_VALUES[item.type],
    0,
  );
  const cap = PAYOUT_CAP_MULTIPLIER * insuranceSum;
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
      return claimResult(step, policyItems);
    }
    return {
      premium: quotePremium(step.items, scenario.customer, index > 0),
    };
  }),
});

