export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_DISCOUNT_RATE = 0.15;
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

// Spec: an item's base premium is 10 % of its insurance value.
// Integer division (not * 0.1) keeps gold amounts exact.
const VALUE_TO_PREMIUM_RATIO = 10;

const basePremiumOf = (itemType: string): number =>
  INSURANCE_VALUES[itemType] / VALUE_TO_PREMIUM_RATIO;

const BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const COMPONENT_TYPES = ["rune", "moonstone"];

const componentBlockAdjustment = (
  items: Item[],
  componentType: string,
): number => {
  const count = items.filter((item) => item.type === componentType).length;
  return count === BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
    : 0;
};

const basePremiumFor = (items: Item[]): number =>
  items.reduce((total, item) => total + basePremiumOf(item.type), 0) +
  COMPONENT_TYPES.reduce(
    (total, componentType) => total + componentBlockAdjustment(items, componentType),
    0,
  );

const surchargeFor = (
  items: Item[],
  rate: number,
  applies: (item: Item) => boolean,
): number =>
  items.reduce(
    (total, item) =>
      total + (applies(item) ? rate * basePremiumOf(item.type) : 0),
    0,
  );

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const curseSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed);

const highEnchantmentSurchargeFor = (items: Item[]): number =>
  surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);

const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const basePremium = basePremiumFor(items);
  const itemSurcharges =
    curseSurchargeFor(items) + highEnchantmentSurchargeFor(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
      ? basePremium * LOYALTY_DISCOUNT_RATE
      : 0;
  const followUpDiscount = isFollowUpContract
    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
    : 0;
  return Math.ceil(
    basePremium +
      itemSurcharges +
      firstInsuranceSurcharge -
      loyaltyDiscount -
      followUpDiscount +
      PROCESSING_FEE,
  );
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const PAYOUT_CAP_MULTIPLIER = 2;
const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
const REDUCED_REIMBURSEMENT_RATE = 0.5;

// Spec: damage to items enchanted at 8 or above is reimbursed at 50 %
// (deductible is applied afterwards, per damage entry).
const reimbursementFor = (
  damage: Damage,
  damagedItem: Item | undefined,
): number =>
  (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
    : damage.amount;

const claimResult = (
  claimStep: ClaimStep,
  policyItems: Item[],
): ClaimResult => {
  const payout = claimStep.incident.damages.reduce((total, damage) => {
    const damagedItem = policyItems.find(
      (item) => item.type === damage.itemType,
    );
    return total + (reimbursementFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE);
  }, 0);
  const insuranceSum = policyItems.reduce(
    (total, item) => total + INSURANCE_VALUES[item.type],
    0,
  );
  const cap = PAYOUT_CAP_MULTIPLIER * insuranceSum;
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
      return claimResult(step, policyItems);
    }
    return {
      premium: quotePremium(step.items, scenario.customer, index > 0),
    };
  }),
});

