76	  const insuranceValue = INSURANCE_VALUES[itemType];
77	  if (insuranceValue === undefined) {
78	    throw new Error(`Unknown item type: ${itemType}`);
79	  }
80	  return insuranceValue;
81	};
82	
83	const basePremiumOf = (itemType: string): number =>
84	  insuranceValueOf(itemType) / VALUE_TO_PREMIUM_RATIO;
85	
86	const sumBy = <T>(values: T[], amountOf: (value: T) => number): number =>
87	  values.reduce((total, value) => total + amountOf(value), 0);
88	
89	const countOf = <T>(values: T[], matches: (value: T) => boolean): number =>
90	  values.filter(matches).length;
91	
92	const countOfType = (items: Item[], type: string): number =>
93	  countOf(items, (item) => item.type === type);
94	
95	const BLOCK_SIZE = 3;
96	const COMPONENT_BLOCK_PREMIUM = 60;
97	
98	const COMPONENT_TYPES = ["rune", "moonstone"];
99	
100	const componentBlockAdjustment = (
101	  items: Item[],
102	  componentType: string,
103	): number => {
104	  const count = countOfType(items, componentType);
105	  return count === BLOCK_SIZE
106	    ? COMPONENT_BLOCK_PREMIUM - BLOCK_SIZE * basePremiumOf(componentType)
107	    : 0;
108	};
109	
110	const totalBasePremium = (items: Item[]): number =>
111	  sumBy(items, (item) => basePremiumOf(item.type)) +
112	  sumBy(COMPONENT_TYPES, (componentType) =>
113	    componentBlockAdjustment(items, componentType),
114	  );
115	
116	const surchargeFor = (
117	  items: Item[],
118	  rate: number,
119	  applies: (item: Item) => boolean,
120	): number =>
121	  sumBy(items, (item) =>
122	    applies(item) ? rate * basePremiumOf(item.type) : 0,
123	  );
124	
125	const isCursed = (item: Item): boolean => item.cursed === true;
126	
127	const isHighlyEnchanted = (item: Item): boolean =>
128	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
129	
130	const quotePremium = (
131	  items: Item[],
132	  customer: Customer,
133	  isFollowUpContract: boolean,
134	): number => {
135	  const basePremium = totalBasePremium(items);
136	  const itemSurcharges =
137	    surchargeFor(items, CURSE_SURCHARGE_RATE, isCursed) +
138	    surchargeFor(items, HIGH_ENCHANTMENT_SURCHARGE_RATE, isHighlyEnchanted);
139	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
140	  const loyaltyDiscount =
141	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
142	      ? basePremium * LOYALTY_DISCOUNT_RATE
143	      : 0;
144	  const followUpDiscount = isFollowUpContract
145	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
146	    : 0;
147	  return Math.ceil(
148	    basePremium +
149	      itemSurcharges +
150	      firstInsuranceSurcharge -
151	      loyaltyDiscount -
152	      followUpDiscount +
153	      PROCESSING_FEE,
154	  );
155	};
156	
157	const DEDUCTIBLE_PER_DAMAGE = 100;
158	const PAYOUT_CAP_MULTIPLIER = 2;
159	const REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
160	const REDUCED_REIMBURSEMENT_RATE = 0.5;
161	
162	// Spec: damage to items enchanted at 8 or above is reimbursed at 50 %
163	// (deductible is applied afterwards, per damage entry).
164	// Callers guarantee the item is covered by the policy.
165	const reimbursementFor = (damage: Damage, damagedItem: Item): number =>
166	  (damagedItem.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
167	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
168	    : damage.amount;
169	
170	const initialCapFor = (policyItems: Item[]): number =>
171	  PAYOUT_CAP_MULTIPLIER *
172	  sumBy(policyItems, (item) => insuranceValueOf(item.type));
173	
174	// Spec: the deductible applies once per damage entry, after any
175	// reimbursement clause.
176	const payoutForDamage = (damage: Damage, policyItems: Item[]): number => {
177	  if (damage.amount < 0) {
178	    throw new Error(`Negative damage amount: ${damage.amount}`);
179	  }
180	  const damagedItem = policyItems.find(
181	    (item) => item.type === damage.itemType,
182	  );
183	  if (damagedItem === undefined) {
184	    throw new Error(`Damaged item not covered by policy: ${damage.itemType}`);
185	  }
186	  return reimbursementFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
187	};
188	
189	const rejectExcessDamages = (damages: Damage[], policyItems: Item[]): void => {
190	  for (const damage of damages) {
191	    const damagedCount = countOf(
192	      damages,
193	      (entry) => entry.itemType === damage.itemType,
194	    );
195	    const insuredCount = countOfType(policyItems, damage.itemType);
196	    if (damagedCount > insuredCount) {
197	      throw new Error(
198	        `More damaged ${damage.itemType} entries (${damagedCount}) than insured (${insuredCount})`,
199	      );
200	    }
201	  }
202	};
203	
204	const settleClaim = (
205	  claimStep: ClaimStep,
206	  policyItems: Item[],
207	  remainingCapBefore: number,
208	): ClaimResult => {
209	  rejectExcessDamages(claimStep.incident.damages, policyItems);
210	  const uncappedPayout = sumBy(claimStep.incident.damages, (damage) =>
211	    payoutForDamage(damage, policyItems),
212	  );
213	  const payout = Math.floor(Math.min(uncappedPayout, remainingCapBefore));
214	  return { payout, remainingCap: remainingCapBefore - payout };
215	};
216	
217	export const runScenario = (scenario: Scenario): ScenarioOutput => {
218	  const remainingCaps = new Map<number, number>();
219	  return {
220	    results: scenario.steps.map((step, index) => {
221	      if (step.op === "claim") {
222	        // Spec: a claim's `policy` field is the index of the quote step
223	        // that created the policy, so that step is always a QuoteStep.
224	        const policyItems = (scenario.steps[step.policy] as QuoteStep).items;
225	        const capBefore =
226	          remainingCaps.get(step.policy) ?? initialCapFor(policyItems);
227	        const result = settleClaim(step, policyItems, capBefore);
228	        remainingCaps.set(step.policy, result.remainingCap);
229	        return result;
230	      }
231	      return {
232	        premium: quotePremium(step.items, scenario.customer, index > 0),
233	      };
234	    }),
235	  };
236	};
